fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let pressed: i32 = if down == 1 && prev == 0 { 1 } else { 0 };
    let released: i32 = if down == 0 && prev == 1 { 1 } else { 0 };
    host::display::state_set(0, down);
    let mut presses: i32 = host::display::state_get(1);
    let mut heldframes: i32 = host::display::state_get(2);
    if pressed == 1 {
        presses = presses + 1;
        host::display::state_set(1, presses);
    }
    if down == 1 {
        heldframes = heldframes + 1;
        host::display::state_set(2, heldframes);
    }
    host::display::clear(0x101010);
    let c1: i32 = if pressed == 1 { 0x00ff00 } else { 0x203020 };
    host::display::fill_rect(30, 40, 40, 40, c1);
    host::display::draw_string(80, 55, "PRESSED THIS FRAME", 0xffffff, 1);
    let c2: i32 = if down == 1 { 0x00aaff } else { 0x202838 };
    host::display::fill_rect(30, 100, 40, 40, c2);
    host::display::draw_string(80, 115, "HELD", 0xffffff, 1);
    let c3: i32 = if released == 1 { 0xff8800 } else { 0x382820 };
    host::display::fill_rect(30, 160, 40, 40, c3);
    host::display::draw_string(80, 175, "RELEASED THIS FRAME", 0xffffff, 1);
    host::display::draw_string(30, 220, "TAPS", 0x808080, 1);
    host::display::draw_number(80, 220, presses, 0xffffff, 2);
    host::display::draw_string(30, 250, "HELD FRAMES", 0x808080, 1);
    host::display::draw_number(130, 250, heldframes, 0xffffff, 2);
    host::display::present();
}
